-- Preserve existing feature grants before refreshing the public catalogue.
UPDATE tenants t JOIN plans p ON t.plan_code = p.code SET t.custom_features = p.features WHERE t.custom_features IS NULL AND t.commercial IS NULL AND p.code IN ('starter','growth','pro');
